// DEMO-4 — the killed_until_ack flag.
// Persisted alongside the session record; scoped per-machine so a kill on local
// doesn't prevent a wake on a remote machine. Cleared via the DAG banner or the
// clear_kill_hold MCP tool.

use std::collections::HashMap;
use std::sync::Mutex;

#[derive(Default)]
pub struct KillHoldStore(Mutex<HashMap<(String, String), bool>>);

impl KillHoldStore {
    pub fn set(&self, machine: &str, session: &str) {
        self.0.lock().unwrap().insert((machine.into(), session.into()), true);
    }
    pub fn clear(&self, machine: &str, session: &str) {
        self.0.lock().unwrap().remove(&(machine.into(), session.into()));
    }
    pub fn is_held(&self, machine: &str, session: &str) -> bool {
        self.0.lock().unwrap().get(&(machine.into(), session.into())).copied().unwrap_or(false)
    }
}

